import { focus } from "../../helpers";
import { ThemeTokens } from "../../theming";
import { StyleFn } from "..";

/**
 * reusable reset styles for "button-like" components
 */
export const buttonReset = {
  cursor: "pointer",
  userSelect: "none",
  whiteSpace: "nowrap",
  backgroundColor: "transparent",
  textTransform: "none",
  textDecoration: "none",
  fontFamily: "inherit",
  // take precedent over the style of a native <a /> element
  color: "inherit",
  // disable the focus ring for mouse, touch and keyboard users
  outline: 0,
  border: 0,
  margin: 0, // Remove margin in Safari
  padding: 0, // Remove padding in Firefox
  WebkitTapHighlightColor: "transparent", // Remove grey highlight
  MozAppearance: "none",
  WebkitAppearance: "none",
  display: "inline-flex",
  boxSizing: "border-box",
  alignItems: "center",
  justifyContent: "center",
  textAlign: "center",
  verticalAlign: "middle",
};

/**
 * Reusable styles for "button-like" components
 * sharing the same interactives states as button variants
 * @param theme
 * @param variant
 */
export const buttonVariant = (
  theme: ThemeTokens,
  mode: "light" | "dark",
  variant:
    | "primary"
    | "secondary"
    | "ghost"
    | "ghost-negative"
    | "success"
    | "warning"
    | "error",
) => {
  const { color } = theme;
  let textColor: string;
  let variantColors: {
    default?: string;
    hover?: string;
    active?: string;
  } = {};

  switch (variant) {
    case "primary":
      textColor = color.text.neutral.minimal[mode];
      variantColors = {
        default: color.surface.accent.default[mode],
        hover: color.surface.accent.hover[mode],
        active: color.surface.accent.active[mode],
      };
      break;
    case "secondary":
      textColor = color.text.accent.default[mode];
      variantColors = {
        default: color.surface.interaction.default[mode],
        hover: color.surface.interaction.hover[mode],
        active: color.surface.interaction.active[mode],
      };
      break;
    case "error":
      textColor = color.text.feedback.error.onsurface[mode];
      variantColors = {
        default: color.surface.feedback.error.default[mode],
        hover: color.surface.feedback.error.hover[mode],
        active: color.surface.feedback.error.active[mode],
      };
      break;
    case "success":
      textColor = color.text.feedback.success.onsurface[mode];
      variantColors = {
        default: color.surface.feedback.success.default[mode],
        hover: color.surface.feedback.success.hover[mode],
        active: color.surface.feedback.success.active[mode],
      };
      break;
    case "warning":
      textColor = color.text.feedback.warning.onsurface[mode];
      variantColors = {
        default: color.surface.feedback.warning.default[mode],
        hover: color.surface.feedback.warning.hover[mode],
        active: color.surface.feedback.warning.active[mode],
      };
      break;
    case "ghost":
      textColor = color.text.accent.default[mode];
      variantColors = {
        hover: color.surface.interaction.hover[mode],
        active: color.surface.interaction.active[mode],
      };
      break;
    case "ghost-negative":
      textColor = color.text.white[mode];
      variantColors = {
        hover: color.surface.interaction.transparenthover[mode],
        active: color.surface.interaction.transparentactive[mode],
      };
      break;
    default:
      textColor = color.text.white[mode];
      break;
  }

  return {
    color: textColor,
    backgroundColor: variantColors.default || "transparent",
    "&:hover": {
      backgroundColor: variantColors.hover || "transparent",
    },
    "&:active": {
      backgroundColor: variantColors.active || "transparent",
    },
    "&[aria-pressed='true']": {
      backgroundColor: variantColors.active || "transparent",
    },
  };
};

export const Button: StyleFn = (theme, mode) => {
  const { color, font, opacity, size } = theme;
  const { focusWithPseudo } = focus(theme, mode);
  const focusDefault = {
    offset: 6, // the offset is 6px as opposed to 2px in design kit, it is because by default focus with pseudo uses 4px for 0px offset and hence 4px+2px=6px.
    radius: size.radius[5],
  };

  return {
    root: {
      extend: [buttonReset],
      minWidth: `${size.spacing[32]}`,
      minHeight: `${size.spacing[24]}`,
      fontSize: font.size.small,
      lineHeight: font.lineheight.medium,
      padding: `${size.spacing[6]} ${size.spacing[16]}`,
      fontWeight: font.weight.bold,
      borderRadius: "3px",
      "& svg, & i": {
        marginLeft: `calc(-${size.spacing[2]})`,
        marginRight: size.spacing[8],
        width: size.spacing[16],
        height: size.spacing[16],
        fontSize: size.spacing[16],
        color: "currentColor",
        fill: "currentColor",
        display: "inline-flex",
      },
      "&:disabled": {
        opacity: opacity.disabled,
        pointerEvents: "none",
      },
    },
    // sizes
    _xsmall: {
      minWidth: size.spacing[16],
      fontSize: font.size.small,
      lineHeight: font.lineheight.xxsmall,
      padding: `0 ${size.spacing[8]}`,
    },
    _small: {
      minWidth: size.spacing[32],
      fontSize: font.size.small,
      lineHeight: font.lineheight.medium,
      padding: `${size.spacing[2]} ${size.spacing[16]}`,
    },
    _medium: {},
    _large: {
      minWidth: size.spacing[48],
      fontSize: font.size.medium,
      lineHeight: font.lineheight.medium,
      padding: `calc(${size.spacing[12]} - 2px) ${size.spacing[24]}`,
      "& svg, & i": {
        width: size.spacing[24],
        height: size.spacing[24],
        fontSize: size.spacing[24],
      },
    },
    _xlarge: {
      minWidth: size.spacing[64],
      fontSize: font.size.large,
      lineHeight: font.lineheight.xlarge,
      padding: `calc(${size.spacing[12]} - 1px) ${size.spacing[32]}`,
      "& svg, & i": {
        width: size.spacing[24],
        height: size.spacing[24],
        fontSize: size.spacing[24],
      },
    },
    // variants
    _ghost: {
      extend: [
        buttonVariant(theme, mode, "ghost"),
        focusWithPseudo(focusDefault),
      ],
    },
    _ghostNegative: {
      extend: [
        buttonVariant(theme, mode, "ghost-negative"),
        focusWithPseudo({
          ...focusDefault,
          colorForce: color.border.neutral.white[mode],
        }),
      ],
    },
    _primary: {
      extend: [
        buttonVariant(theme, mode, "primary"),
        focusWithPseudo(focusDefault),
      ],
    },
    _secondary: {
      // same as ghost variant with a border
      extend: [
        buttonVariant(theme, mode, "secondary"),
        focusWithPseudo(focusDefault),
      ],
      borderColor: color.border.accent.default[mode],
    },
    _success: {
      extend: [
        buttonVariant(theme, mode, "success"),
        focusWithPseudo(focusDefault),
      ],
    },
    _warning: {
      extend: [
        buttonVariant(theme, mode, "warning"),
        focusWithPseudo(focusDefault),
      ],
    },
    _error: {
      extend: [
        buttonVariant(theme, mode, "error"),
        focusWithPseudo(focusDefault),
      ],
    },
  };
};
